def compute_drift(metrics_list):
    result = {}
    for metric in METRICS:
        vals = [m[metric] for m in metrics_list]
        gen0, genN = vals[0], vals[-1]
        drift_pct = round((genN - gen0) / abs(gen0) * 100, 2) if abs(gen0) > 1e-12 else 0.0
        result[metric] = {
            "gen0": round(gen0, 6),
            f"gen{len(vals)-1}": round(genN, 6),
            "drift_pct": drift_pct,
        }
    return result


def run_5method(metrics_list, n_perm=1000):
    pairs_results = {}
    all_p_values = []
    p_value_keys = []

    for cn in CANARY:
        for dn in DOWNSTREAM:
            pair_key = f"{cn}->{dn}"
            c = ma_extract(metrics_list, cn)
            d = ma_extract(metrics_list, dn)

            pair = {}
            for method_name, method_fn in MA_METHODS.items():
                try:
                    res = method_fn(c, d, cn, dn)
                except Exception as e:
                    res = {"error": str(e)}
                pair[method_name] = res

                p = res.get("p_value") or res.get("p_raw")
                if p is not None:
                    all_p_values.append(p)
                    p_value_keys.append((pair_key, method_name))

            pairs_results[pair_key] = pair

    if all_p_values:
        _, fdr_ps, _, _ = multipletests(all_p_values, method="fdr_bh")
        for i, (pk, mn) in enumerate(p_value_keys):
            pairs_results[pk][mn]["p_fdr"] = round(float(fdr_ps[i]), 6)

    return pairs_results


def summarize_votes(pairs_results):
    summary = {}
    for pair_key, methods in pairs_results.items():
        votes = {}
        for method_name, res in methods.items():
            if "error" in res:
                votes[method_name] = "error"
                continue
            sig = res.get("significant", res.get("p_fdr", res.get("p_value", 1.0)))
            if isinstance(sig, bool):
                votes[method_name] = "significant" if sig else "not_significant"
            elif isinstance(sig, (int, float)):
                votes[method_name] = "significant" if sig < 0.05 else "not_significant"
            else:
                votes[method_name] = str(sig)
        summary[pair_key] = votes
    return summary


def analyze_experiment(exp_name, exp_dir):
    config_path = os.path.join(exp_dir, "config.json")
    config = {}
    if os.path.exists(config_path):
        with open(config_path) as f:
            config = json.load(f)

    metrics_list = assemble_all_metrics(exp_dir)
    if metrics_list is None:
        return {"experiment": exp_name, "status": "no_metrics", "error": "No metrics found"}

    n_gens = len(metrics_list)
    print(f"  {exp_name}: {n_gens} generations", flush=True)

    drift = compute_drift(metrics_list)
    pairs_results = run_5method(metrics_list)
    votes = summarize_votes(pairs_results)

